type Item = {
  type: string;
};

type QuoteStep = {
  op: "quote";
  items: Item[];
};

type Scenario = {
  steps: QuoteStep[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;

const basePremiumOf = (item: Item): number => {
  return item.type === "sword" ? 100 : 0;
};

const quote = (step: QuoteStep): QuoteResult => {
  const itemsPremium = step.items.reduce(
    (sum, item) => sum + basePremiumOf(item) * (1 + FIRST_INSURANCE_RATE),
    0,
  );

  return { premium: itemsPremium + PROCESSING_FEE };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return { results: scenario.steps.map(quote) };
};

