export type QuoteResult = {
  premium: number;
};

export type ScenarioResult = {
  results: QuoteResult[];
};

type Item = {
  type: string;
};

type QuoteStep = {
  op: "quote";
  items: Item[];
};

type Customer = {
  yearsWithMHPCO: number;
};

type Scenario = {
  customer: Customer;
  steps: QuoteStep[];
};

const PROCESSING_FEE = 5;
// No test yet drives unknown item types; the spec ultimately requires an error.
const UNKNOWN_ITEM_BASE_PREMIUM = 0;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUMS;

const isInsurable = (type: string): type is InsurableItemType =>
  type in BASE_PREMIUMS;

const basePremiumOf = (item: Item): number =>
  isInsurable(item.type) ? BASE_PREMIUMS[item.type] : UNKNOWN_ITEM_BASE_PREMIUM;

const policyBasePremiumOf = (items: Item[]): number =>
  items.reduce((sum, item) => sum + basePremiumOf(item), 0);

const quote = (step: QuoteStep): QuoteResult => {
  const basePremium = policyBasePremiumOf(step.items);
  const firstInsuranceSurcharge = percentOf(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );

  return {
    premium: Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE),
  };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return { results: scenario.steps.map(quote) };
};

