export type QuoteResult = {
  premium: number;
};

export type ScenarioResult = {
  results: QuoteResult[];
};

const BASE_PREMIUMS = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUMS;

type Item = {
  type: InsurableItemType;
};

type QuoteStep = {
  op: "quote";
  items: Item[];
};

type Customer = {
  yearsWithMHPCO: number;
};

type Scenario = {
  customer: Customer;
  steps: QuoteStep[];
};

const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;

const percentOf = (amount: number, percent: number): number =>
  (amount * percent) / 100;

// The MHPCO always rounds in its own favour: premiums (which the customer
// pays) go up. Payouts round down, but no test demands that yet.
const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];

// Three components of the same type form a "building block" priced as a unit
// rather than per item.
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const areAllSameType = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

// Only whole-policy blocks are recognised so far; a policy that merely
// contains a block is the next test's job.
const formsASingleBlock = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE && areAllSameType(items);

const policyBasePremiumOf = (items: Item[]): number => {
  if (formsASingleBlock(items)) {
    return BLOCK_BASE_PREMIUM;
  }

  return items.reduce((sum, item) => sum + itemBasePremiumOf(item), 0);
};

const quote = (step: QuoteStep): QuoteResult => {
  const basePremium = policyBasePremiumOf(step.items);
  const initialAssessmentSurcharge = percentOf(
    basePremium,
    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
  );

  return {
    premium: roundedUpInMHPCOsFavour(
      basePremium + initialAssessmentSurcharge + PROCESSING_FEE,
    ),
  };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return { results: scenario.steps.map(quote) };
};

