  formsBuildingBlock(alikeItems)
    ? BUILDING_BLOCK_BASE_PREMIUM
    : sumOf(alikeItems.map(itemBasePremiumOf));

const policyBasePremiumOf = (items: Item[]): number =>
  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));

