import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result).toEqual({ results: [{ premium: 5 }] });
  });

  // --- Base premiums per main item (plus fee, newcomer surcharges apply) ---
  it("single sword base premium 100 G → premium 115 G (100 + 10 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("single amulet base premium 60 G → premium 71 G (60 + 6 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("single staff base premium 80 G → premium 93 G (80 + 8 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 93 }] });
  });
  it("single potion base premium 40 G → premium 49 G (40 + 4 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 49 }] });
  });

  // --- Components and the building block of 3 alike ---
  it("single rune base premium 25 G → premium 33 G (25 + 2.5 first insurance + 5 fee, rounded up)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 33 }] });
  });
  it("2 runes → 50 G base premium → premium 60 G (50 + 5 first insurance + 5 fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });

    expect(result).toEqual({ results: [{ premium: 60 }] });
  });
  it("3 runes → 60 G base premium (block applies) → premium 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 71 }] });
  });
  it("4 runes → 100 G base premium (no block — block requires exactly 3) → premium 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 115 }] });
  });
  it("7 runes → 175 G base premium → premium 198 G (197.5 rounded up)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" as const })) },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 198 }] });
  });
  it("2 runes + 1 moonstone → 75 G base premium (no block: different types) → premium 88 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 88 }] });
  });
  it("3 runes + 3 moonstones → 120 G base premium (two separate blocks) → premium 137 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 137 }] });
  });

  // --- Premium modifiers in isolation ---
  it("cursed sword adds 50 % risk surcharge → 50 G on a 100 G base premium → premium 165 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: true }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 165 }] });
  });
  it("sword with exactly enchantment 5 adds 30 % high-enchantment surcharge → premium 145 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 5, cursed: false }],
        },
      ],
    });

    expect(result).toEqual({ results: [{ premium: 145 }] });
  });
  it.todo("sword with enchantment 4 → no high-enchantment surcharge");
  it.todo("cursed sword with enchantment 5 → both surcharges apply");
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge");
  it.todo("second contract receives a 15 % follow-up discount");

  // --- Modifier scope on multi-item policies ---
  it.todo(
    "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G (only on the cursed item) → 210 G before further modifiers and fee",
  );
  it.todo("policy-wide modifiers apply to the policy base premium (sum of item base premiums)");

  // --- Rounding in the MHPCO's favor ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo(
    "long-standing customer's second contract, cursed sword (steel, enchantment 7) → premium 160 G",
  );

  // --- Claim processing: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");

  // --- Claim processing: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo(
    "dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)",
  );

  // --- Cap ---
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (premium with modifiers 165 G) → cap 2000 G (based on unmodified insurance value)");
  it.todo("policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo(
    "sword policy (cap 2000 G), two successive claims of 1500 G → second payout 600 G, remainingCap 0 G",
  );

  // --- Multiple items of the same type ---
  it.todo("policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("two sword damage entries on a two-sword policy → each treated as a separate damage with its own deductible");

  // --- Error cases ---
  it.todo("quote with an unknown item type (e.g. broomstick) → error");
  it.todo("claim referencing an item not part of the policy (amulet damaged, only a sword insured) → error");
  it.todo("claim referencing a damage entry with an unknown item type → error");
  it.todo("claim with more damage entries of a type than the policy covers → error");
  it.todo("claim containing a damage entry with amount -200 → error");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes { results } JSON to stdout");
  it.todo("CLI exits with a non-zero status code and writes an error to stderr on an invalid scenario");
});

