const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;

// The MHPCO rounds payouts (which it pays out) down.
const roundedDownInMHPCOsFavour = (payout: number): number =>
  Math.floor(payout);

const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type];

// A policy is created by a quote step and remembers how much of its cap the
// customer has already claimed.
type Policy = {
  items: Item[];
  remainingCap: number;
};

const damagePayoutOf = (damage: Damage): number =>
  damage.amount - DEDUCTIBLE_PER_DAMAGE;

const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
  const payout = roundedDownInMHPCOsFavour(
    sumOf(step.incident.damages.map(damagePayoutOf)),
  );
  policy.remainingCap -= payout;

  return { payout, remainingCap: policy.remainingCap };
};

const policyFor = (items: Item[]): Policy => ({
  items,
  remainingCap: CAP_MULTIPLIER * sumOf(items.map(insuranceValueOf)),
});

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();
  const results: StepResult[] = [];

  scenario.steps.forEach((step, stepIndex) => {
    if (step.op === "quote") {
      policies.set(stepIndex, policyFor(step.items));
      results.push(
        quote(step, {
          customer: scenario.customer,
          contractIndex: policies.size - 1,
        }),
      );
      return;
    }

    results.push(claim(step, policies.get(step.policy)!));
  });

  return { results };
};

