type StepOutcome = {
  result: StepResult;
  policyKey: number;
  policy: Policy;
};

const withOutcomeRecorded = (office: Office, outcome: StepOutcome): Office => ({
  policies: new Map(office.policies).set(outcome.policyKey, outcome.policy),
  results: [...office.results, outcome.result],
});

