  office: Office,
  step: Step,
  stepIndex: number,
  customer: Customer,
): StepOutcome => {
  if (step.op === "quote") {
    const contract = { customer, contractIndex: office.policies.size };

    return {
      result: quote(step, contract),
      policyKey: stepIndex,
      policy: policyFor(step.items),
    };
  }

  const claimed = claim(step, office.policies.get(step.policy)!);

  return {
    result: claimed.result,
    policyKey: step.policy,
    policy: claimed.policy,
  };
};

