  alikeItems.length === BUILDING_BLOCK_SIZE;

const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
  formsBuildingBlock(alikeItems)
    ? BUILDING_BLOCK_BASE_PREMIUM
