  appliesTo: (subject: Subject) => boolean;
  percent: number;
};

const modifierTotalOf = <Subject>(
  modifiers: Modifier<Subject>[],
  subject: Subject,
  basePremium: number,
): number =>
  sumOf(
    modifiers
      .filter((modifier) => modifier.appliesTo(subject))
      .map((modifier) => percentOf(basePremium, modifier.percent)),
  );

