const damagePayoutOf = (damage: Damage, item: Item): number =>
  reimbursementOf(damage, item) - DEDUCTIBLE_PER_DAMAGE;

// The insured item a damage entry is about.
const damagedItemIn = (policy: Policy, damage: Damage): Item =>
  policy.items.find((item) => item.type === damage.itemType)!;

const incidentPayoutOf = (incident: Incident, policy: Policy): number =>
  roundedDownInMHPCOsFavour(
    sumOf(
      incident.damages.map((damage) =>
        damagePayoutOf(damage, damagedItemIn(policy, damage)),
